import socketfrom ast import literal_evalfrom GUI.kv import ip_addressclient_s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)msg = bytes('UDP cli', 'utf-8')client_s.sendto(msg, (ip_address, 12345))data, addr = client_s.recvfrom(4096)data = eval(data)print(data, type(data))client_s.close()